message:
Running command: cat > /workspace/repro7.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sdb.h"

/* Declare internal functions */
extern void sdb_ns_free(Sdb *s);

int main(void) {
    Sdb *a, *b, *c;

    a = sdb_new0();
    b = sdb_new0();
    c = sdb_new0();

    printf("a=%p b=%p c=%p\n", (void*)a, (void*)b, (void*)c);
    printf("Initial: a->refs=%d b->refs=%d c->refs=%d\n", a->refs, b->refs, c->refs);

    /* b has two namespaces pointing to c */
    sdb_ns_set(b, "x", c);
    printf("After b->x: c->refs=%d\n", c->refs);
    sdb_ns_set(b, "y", c);
    printf("After b->y: c->refs=%d\n", c->refs);

    /* a has two namespaces pointing to b */
    sdb_ns_set(a, "n1", b);
    printf("After a->n1: b->refs=%d\n", b->refs);
    sdb_ns_set(a, "n2", b);
    printf("After a->n2: b->refs=%d\n", b->refs);

    printf("\nCalling sdb_ns_free(a)...\n");
    fflush(stdout);

    /* Call sdb_ns_free directly (which is what sdb_fini calls) */
    sdb_ns_free(a);

    printf("After sdb_ns_free(a)\n");
    printf("a->ns = %p\n", (void*)a->ns);

    printf("Calling sdb_free(a)...\n");
    sdb_free(a);

    printf("Done\n");
    return 0;
}
EOF
cd /workspace && gcc -fsanitize=address -g -I /workspace/repo-vul/src-vul/radare2/shlr/sdb/src -o repro7 repro7.c /workspace/repo-vul/src-vul/radare2/shlr/sdb/src/libsdb.a -lpthread -ldl -lm 2>&1 && ./repro7; echo "Exit: $?"

